/*selectSellerMpClDlvryCarList*/
SELECT CODE AS CAR_CODE , TEXT1 AS CAR_NUMBER , TEXT2 AS USER_NAME , TEXT3 AS PHONE_NUM , TO_CHAR(TO_DATE(ADD_DATE,'YYYYMMDD'),'YYYY/MM/DD') AS ADD_DATE FROM ICOMCOD2 /* 회사별 코드관리 */ WHERE 1=1 AND TYPE = 'CA01' AND COMPANY_CODE = #{st_com_code}
AND TEXT1 LIKE '%' || #{st_car_num} || '%'
AND TEXT2 LIKE '%' || #{st_user_name} || '%'
ORDER BY CODE
